window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["cal"]={html:"<div class=\"own-cal\">\n  <header class=\"nav\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Northwind home\">\n      <span class=\"brand-mark\" aria-hidden=\"true\"></span>Northwind\n    </a>\n    <nav class=\"nav-links\" aria-label=\"Primary\">\n      <a href=\"#product\">Product</a>\n      <a href=\"#product\">Solutions</a>\n      <a href=\"#resources\">Resources</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#enterprise\">Enterprise</a>\n    </nav>\n    <div class=\"nav-right\">\n      <a class=\"nav-signin\" href=\"#\">Sign in</a>\n      <a class=\"btn btn-primary\" href=\"#\">Sign up free</a>\n    </div>\n  </header>\n\n  <section class=\"hero\" id=\"top\" aria-labelledby=\"heroH\">\n    <div class=\"wrap hero-grid\">\n      <div class=\"hero-copy\">\n        <p class=\"badge-pill\">New · Ops dashboards 2.0</p>\n        <h1 id=\"heroH\">The better way to run your operations reviews</h1>\n        <p class=\"lead\">Northwind turns scattered regional data into one scheduling-grade command surface — dashboards, throughput, and alerts that everyone trusts.</p>\n        <div class=\"hero-actions\">\n          <a class=\"btn btn-primary\" href=\"#\">Start free</a>\n          <a class=\"btn btn-secondary\" href=\"#product\">See it work</a>\n        </div>\n        <div class=\"hero-tabs\" role=\"tablist\" aria-label=\"Team size\">\n          <button type=\"button\" role=\"tab\" class=\"tab\" aria-selected=\"true\">Personal</button>\n          <button type=\"button\" role=\"tab\" class=\"tab\" aria-selected=\"false\">Teams</button>\n          <button type=\"button\" role=\"tab\" class=\"tab\" aria-selected=\"false\">Enterprise</button>\n        </div>\n      </div>\n      <div class=\"hero-mock\" aria-hidden=\"true\">\n        <div class=\"mock-head\"><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"mock-title\">Northwind · Weekly ops</span></div>\n        <div class=\"mock-body\">\n          <div class=\"mock-cal\">\n            <div class=\"mock-cal-head\"><b>October</b><span>Region: all</span></div>\n            <div class=\"mock-grid\">\n              <i></i><i></i><i class=\"on\"></i><i></i><i></i><i></i><i></i>\n              <i></i><i class=\"on\"></i><i></i><i></i><i></i><i></i><i></i>\n              <i></i><i></i><i></i><i class=\"on\"></i><i></i><i></i><i></i>\n              <i></i><i></i><i></i><i></i><i class=\"on\"></i><i></i><i></i>\n            </div>\n          </div>\n          <div class=\"mock-slots\">\n            <span class=\"slot-time\">Throughput</span>\n            <span class=\"slot on\">2.8M / min</span>\n            <span class=\"slot\">1.4M / min</span>\n            <span class=\"slot\">0.9M / min</span>\n            <button type=\"button\" class=\"btn btn-primary mock-confirm\">Confirm</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"features\" id=\"product\" aria-labelledby=\"featH\">\n    <div class=\"wrap\">\n      <p class=\"eyebrow center\">With us, operations are easy</p>\n      <h2 id=\"featH\" class=\"display-lg center\">Everything your team schedules, in one place</h2>\n      <div class=\"feature-grid\">\n        <article class=\"feature-card\">\n          <span class=\"ficon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M3 9h18M8 4v16\"/></svg></span>\n          <h3>Unified dashboards</h3>\n          <p>Every region, metric and owner on one timeline your team can act on.</p>\n        </article>\n        <article class=\"feature-card\">\n          <span class=\"ficon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19V5M4 19h16M8 15l3-4 3 3 4-6\"/></svg></span>\n          <h3>Throughput analytics</h3>\n          <p>Live and historical throughput with alerting that fires before the drop.</p>\n        </article>\n        <article class=\"feature-card\">\n          <span class=\"ficon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 3\"/></svg></span>\n          <h3>Automated reviews</h3>\n          <p>Schedule recurring ops reviews and let Northwind gather the numbers.</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"product\" id=\"resources\" aria-labelledby=\"prodH\">\n    <div class=\"wrap product-grid\">\n      <div class=\"product-copy\">\n        <p class=\"eyebrow\">Your all-purpose operations app</p>\n        <h2 id=\"prodH\" class=\"display-lg\">Show the product, not an illustration</h2>\n        <p class=\"lead\">Northwind embeds the real workspace — calendars, throughput panels, and region tables — directly into the flow.</p>\n        <ul class=\"check-list\">\n          <li>Realtime region federation</li>\n          <li>Sub-second refresh with retention</li>\n          <li>Alert routing to the right crew</li>\n        </ul>\n        <a class=\"btn btn-secondary\" href=\"#\">Explore the workspace</a>\n      </div>\n      <div class=\"mock-card\" aria-hidden=\"true\">\n        <div class=\"mock-rows\">\n          <div class=\"mrow\"><span class=\"chip chip-emerald\">APAC</span><b>2.8M</b><span class=\"up\">+6.2%</span></div>\n          <div class=\"mrow\"><span class=\"chip chip-orange\">EMEA</span><b>1.9M</b><span class=\"up\">+2.1%</span></div>\n          <div class=\"mrow\"><span class=\"chip chip-violet\">AMER</span><b>1.4M</b><span class=\"down\">-1.4%</span></div>\n          <div class=\"mrow\"><span class=\"chip chip-pink\">LATAM</span><b>0.8M</b><span class=\"up\">+3.9%</span></div>\n        </div>\n        <div class=\"mock-bars\">\n          <span style=\"--h:70%\"></span><span style=\"--h:46%\"></span><span style=\"--h:88%\"></span><span style=\"--h:60%\"></span><span style=\"--h:96%\"></span><span style=\"--h:52%\"></span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"testimonials\" aria-labelledby=\"quoteH\">\n    <div class=\"wrap\">\n      <h2 id=\"quoteH\" class=\"display-lg center\">Loved by operations teams</h2>\n      <div class=\"quote-grid\">\n        <article class=\"quote-card\">\n          <div class=\"quote-top\"><span class=\"avatar av-1\">JL</span><div><b>Jo Lang</b><span class=\"muted\">Ops Lead, fictive</span></div><span class=\"stars\" aria-hidden=\"true\">★★★★★</span></div>\n          <p>“Our weekly review went from three hours to twenty minutes. Northwind just has the numbers ready.”</p>\n        </article>\n        <article class=\"quote-card\">\n          <div class=\"quote-top\"><span class=\"avatar av-2\">RM</span><div><b>Rhea M.</b><span class=\"muted\">Director, fictive</span></div><span class=\"stars\" aria-hidden=\"true\">★★★★★</span></div>\n          <p>“The alerts arrive before throughput dips. That alone paid for the whole platform.”</p>\n        </article>\n        <article class=\"quote-card\">\n          <div class=\"quote-top\"><span class=\"avatar av-3\">PT</span><div><b>Paolo T.</b><span class=\"muted\">Analyst, fictive</span></div><span class=\"stars\" aria-hidden=\"true\">★★★★★</span></div>\n          <p>“Region tables that finally agree with each other. Trust in our own dashboards is back.”</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"pricing\" id=\"pricing\" aria-labelledby=\"priceH\">\n    <div class=\"wrap\">\n      <h2 id=\"priceH\" class=\"display-lg center\">Simple, transparent pricing</h2>\n      <div class=\"pricing-grid\">\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Starter</h3>\n          <p class=\"tier-price\">$0</p>\n          <p class=\"muted\">For a single region and a single team.</p>\n          <ul class=\"check-list\"><li>1 region</li><li>7-day retention</li><li>Community support</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Grid</h3>\n          <p class=\"tier-price\">$49</p>\n          <p class=\"muted\">For growing multi-region operations.</p>\n          <ul class=\"check-list\"><li>18 regions</li><li>13-month retention</li><li>Alert routing</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"tier tier-featured\" id=\"enterprise\">\n          <span class=\"badge-pill dark\">Featured</span>\n          <h3 class=\"tier-name\">Teams</h3>\n          <p class=\"tier-price\">$99</p>\n          <p class=\"muted\">For federated grids with SLA needs.</p>\n          <ul class=\"check-list\"><li>41 regions</li><li>36-month retention</li><li>24/7 support</li></ul>\n          <a class=\"btn btn-primary\" href=\"#\">Start free</a>\n        </article>\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Enterprise</h3>\n          <p class=\"tier-price\">Custom</p>\n          <p class=\"muted\">For regulated fleets and single-tenant needs.</p>\n          <ul class=\"check-list\"><li>Unlimited regions</li><li>SSO &amp; audit</li><li>Dedicated crew</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Contact sales</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"cta-band\">\n    <div class=\"wrap cta-inner\">\n      <h2 class=\"display-sm\">Smarter, simpler operations reviews</h2>\n      <p class=\"muted\">Start free — no card, no setup call, no guesswork.</p>\n      <a class=\"btn btn-primary btn-lg\" href=\"#\">Sign up free</a>\n    </div>\n  </section>\n\n  <footer class=\"foot\">\n    <div class=\"wrap foot-grid\">\n      <div class=\"foot-brand\">\n        <p class=\"foot-word\">Northwind</p>\n        <p class=\"foot-tag\">Operations analytics, scheduled.</p>\n      </div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Product</p><a href=\"#\">Dashboards</a><a href=\"#\">Streaming</a><a href=\"#\">Alerts</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Solutions</p><a href=\"#\">Operations</a><a href=\"#\">Data teams</a><a href=\"#\">Enterprise</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Company</p><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Resources</p><a href=\"#\">Docs</a><a href=\"#\">Status</a><a href=\"#\">Security</a></div>\n    </div>\n    <div class=\"wrap foot-bottom\">\n      <p>Northwind is a fictional product. Sample data — showcase only.</p>\n      <span>© 2026 Northwind</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Cal.com design language ═══════════════\n   Scoped under .own-cal. Tokens from design-md/cal/DESIGN.md. White canvas,\n   black primary CTAs, Cal Sans display (substituted by Inter 600 with negative\n   tracking), light-gray cards holding product UI fragments, pastel badge set,\n   and the single dark footer that closes the page. */\n\n.own-cal {\n  --canvas: #ffffff;\n  --surface-soft: #f8f9fa;\n  --surface-card: #f5f5f5;\n  --surface-strong: #e5e7eb;\n  --surface-dark: #101010;\n  --surface-dark-elevated: #1a1a1a;\n  --ink: #111111;\n  --body: #374151;\n  --muted: #6b7280;\n  --muted-soft: #898989;\n  --hairline: #e5e7eb;\n  --hairline-soft: #f3f4f6;\n  --on-primary: #ffffff;\n  --on-dark: #ffffff;\n  --on-dark-soft: #a1a1aa;\n  --brand-accent: #3b82f6;\n  --badge-orange: #fb923c;\n  --badge-pink: #ec4899;\n  --badge-violet: #8b5cf6;\n  --badge-emerald: #34d399;\n  --error: #ef4444;\n\n  --display: \"Cal Sans\", \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --body-font: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n\n  --gut: clamp(20px, 4.4cqi, 32px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--body-font);\n  font-size: 16px;\n  font-weight: 400;\n  line-height: 1.5;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n}\n.own-cal *,\n.own-cal *::before,\n.own-cal *::after { box-sizing: border-box; }\n.own-cal :focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }\n.own-cal a { color: inherit; text-decoration: none; }\n.own-cal .wrap { max-width: 1200px; margin: 0 auto; padding: 0 var(--gut); }\n.own-cal .center { text-align: center; }\n.own-cal .muted { color: var(--muted); }\n.own-cal .lead { color: var(--body); font-size: 17px; line-height: 1.55; }\n\n/* ── type ─────────────────────────────────────────────────────────────── */\n.own-cal .display-lg {\n  font-family: var(--display); font-weight: 600;\n  font-size: clamp(30px, 4.2cqi, 48px); line-height: 1.1; letter-spacing: -.045em; margin: 0;\n}\n.own-cal .display-sm {\n  font-family: var(--display); font-weight: 600;\n  font-size: clamp(24px, 2.6cqi, 28px); line-height: 1.2; letter-spacing: -.02em; margin: 0;\n}\n.own-cal .eyebrow {\n  font-family: var(--body-font); font-weight: 500; font-size: 13px;\n  color: var(--muted); margin: 0 0 12px;\n}\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-cal .btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 40px; padding: 0 20px; border-radius: 8px;\n  font-family: var(--body-font); font-weight: 600; font-size: 14px;\n  border: 1px solid transparent; cursor: pointer; white-space: nowrap;\n  transition: background-color .15s ease, border-color .15s ease, filter .15s ease;\n}\n.own-cal .btn-primary { background: var(--ink); color: var(--on-primary); }\n.own-cal .btn-primary:hover { background: #242424; }\n.own-cal .btn-secondary { background: var(--canvas); color: var(--ink); border-color: var(--hairline); }\n.own-cal .btn-secondary:hover { border-color: #d1d5db; }\n.own-cal .btn-lg { height: 44px; padding: 0 26px; font-size: 15px; }\n.own-cal .badge-pill {\n  display: inline-block; background: var(--surface-card); color: var(--ink);\n  font-size: 13px; font-weight: 500; padding: 4px 12px; border-radius: 9999px; margin-bottom: 20px;\n}\n.own-cal .badge-pill.dark { background: rgba(255,255,255,.12); color: var(--on-dark); }\n\n/* ── nav ──────────────────────────────────────────────────────────────── */\n.own-cal .nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 32px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(255,255,255,.92); border-bottom: 1px solid var(--hairline-soft);\n  backdrop-filter: blur(8px);\n}\n.own-cal .brand { display: inline-flex; align-items: center; gap: 9px; font-family: var(--display); font-weight: 600; font-size: 19px; letter-spacing: -.03em; }\n.own-cal .brand-mark { width: 22px; height: 22px; border-radius: 9999px; background: var(--ink); position: relative; display: inline-block; }\n.own-cal .brand-mark::after { content: \"\"; position: absolute; inset: 6px; border-radius: 9999px; background: var(--canvas); }\n.own-cal .nav-links { display: flex; align-items: center; gap: 26px; }\n.own-cal .nav-links a { font-size: 14px; font-weight: 500; color: var(--body); transition: color .15s; }\n.own-cal .nav-links a:hover { color: var(--ink); }\n.own-cal .nav-right { margin-left: auto; display: flex; align-items: center; gap: 16px; }\n.own-cal .nav-signin { font-size: 14px; font-weight: 500; }\n.own-cal .nav-signin:hover { color: var(--muted); }\n\n/* ── hero ─────────────────────────────────────────────────────────────── */\n.own-cal .hero { padding: var(--section) 0; }\n.own-cal .hero-grid { display: grid; grid-template-columns: 7fr 5fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-cal .hero h1 {\n  font-family: var(--display); font-weight: 600;\n  font-size: clamp(38px, 5.4cqi, 64px); line-height: 1.05; letter-spacing: -.03em; margin: 0 0 20px;\n}\n.own-cal .hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin: 28px 0; }\n.own-cal .hero-tabs {\n  display: inline-flex; gap: 4px; padding: 6px; border-radius: 9999px; background: var(--surface-soft);\n}\n.own-cal .hero-tabs .tab {\n  background: none; border: 0; cursor: pointer; padding: 8px 16px; border-radius: 8px;\n  font-family: var(--body-font); font-size: 14px; font-weight: 500; color: var(--muted);\n  transition: background-color .2s ease, color .2s ease, box-shadow .2s ease;\n}\n.own-cal .hero-tabs .tab[aria-selected=\"true\"] { background: var(--canvas); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.08); }\n\n/* product mock in hero */\n.own-cal .hero-mock { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 16px; box-shadow: 0 4px 12px rgba(0,0,0,.08); overflow: hidden; }\n.own-cal .mock-head { display: flex; align-items: center; gap: 6px; padding: 12px 16px; border-bottom: 1px solid var(--hairline-soft); }\n.own-cal .mock-head .dot { width: 10px; height: 10px; border-radius: 9999px; background: var(--surface-strong); }\n.own-cal .mock-title { margin-left: 10px; font-size: 12px; color: var(--muted); font-weight: 500; }\n.own-cal .mock-body { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; padding: 18px; }\n.own-cal .mock-cal-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 12px; }\n.own-cal .mock-cal-head b { font-size: 14px; }\n.own-cal .mock-cal-head span { font-size: 11px; color: var(--muted); }\n.own-cal .mock-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px; }\n.own-cal .mock-grid i { display: block; aspect-ratio: 1; border-radius: 4px; background: var(--surface-card); }\n.own-cal .mock-grid i.on { background: var(--ink); }\n.own-cal .mock-slots { display: flex; flex-direction: column; gap: 8px; }\n.own-cal .slot-time { font-size: 11px; color: var(--muted); font-weight: 500; text-transform: uppercase; letter-spacing: .06em; }\n.own-cal .slot { display: block; padding: 9px 12px; border-radius: 8px; border: 1px solid var(--hairline); font-size: 13px; font-weight: 600; text-align: center; }\n.own-cal .slot.on { background: var(--ink); color: var(--on-primary); border-color: var(--ink); }\n.own-cal .mock-confirm { width: 100%; margin-top: auto; height: 36px; }\n\n/* ── features ────────────────────────────────────────────────────────── */\n.own-cal .features { padding: var(--section) 0; }\n.own-cal .features .display-lg { max-width: 640px; margin: 0 auto; }\n.own-cal .feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }\n.own-cal .feature-card { background: var(--surface-card); border-radius: 12px; padding: 32px; }\n.own-cal .ficon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 8px; background: var(--canvas); margin-bottom: 20px; }\n.own-cal .ficon svg { width: 22px; height: 22px; fill: none; stroke: var(--ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-cal .feature-card h3 { font-family: var(--body-font); font-weight: 600; font-size: 18px; margin: 0 0 10px; }\n.own-cal .feature-card p { color: var(--body); margin: 0; }\n\n/* ── product ─────────────────────────────────────────────────────────── */\n.own-cal .product { padding: var(--section) 0; }\n.own-cal .product-grid { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-cal .product-copy .display-lg { max-width: 12ch; margin-bottom: 18px; }\n.own-cal .check-list { list-style: none; margin: 22px 0; padding: 0; display: grid; gap: 12px; }\n.own-cal .check-list li { position: relative; padding-left: 28px; color: var(--body); }\n.own-cal .check-list li::before { content: \"\"; position: absolute; left: 0; top: 3px; width: 18px; height: 18px; border-radius: 9999px; background: var(--surface-card); border: 1px solid var(--hairline); }\n.own-cal .check-list li::after { content: \"\"; position: absolute; left: 5px; top: 8px; width: 8px; height: 5px; border-left: 2px solid var(--ink); border-bottom: 2px solid var(--ink); transform: rotate(-45deg); }\n.own-cal .mock-card { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 12px; padding: 24px; }\n.own-cal .mock-rows { display: grid; gap: 12px; }\n.own-cal .mrow { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding-bottom: 12px; border-bottom: 1px solid var(--hairline-soft); }\n.own-cal .mrow:last-child { border-bottom: 0; padding-bottom: 0; }\n.own-cal .mrow b { font-variant-numeric: tabular-nums; font-size: 15px; }\n.own-cal .chip { font-size: 12px; font-weight: 500; padding: 3px 10px; border-radius: 9999px; color: var(--ink); }\n.own-cal .chip-emerald { background: color-mix(in srgb, var(--badge-emerald) 30%, #fff); }\n.own-cal .chip-orange { background: color-mix(in srgb, var(--badge-orange) 30%, #fff); }\n.own-cal .chip-violet { background: color-mix(in srgb, var(--badge-violet) 26%, #fff); }\n.own-cal .chip-pink { background: color-mix(in srgb, var(--badge-pink) 24%, #fff); }\n.own-cal .up { color: #059669; font-size: 13px; font-weight: 600; }\n.own-cal .down { color: var(--error); font-size: 13px; font-weight: 600; }\n.own-cal .mock-bars { display: flex; align-items: flex-end; gap: 8px; height: 90px; margin-top: 20px; }\n.own-cal .mock-bars span { flex: 1; height: var(--h); background: var(--surface-card); border-radius: 6px 6px 0 0; }\n\n/* ── testimonials ────────────────────────────────────────────────────── */\n.own-cal .testimonials { padding: var(--section) 0; background: var(--surface-soft); }\n.own-cal .quote-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 44px; }\n.own-cal .quote-card { background: var(--canvas); border-radius: 12px; padding: 24px; border: 1px solid var(--hairline-soft); }\n.own-cal .quote-top { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }\n.own-cal .quote-top > div { display: flex; flex-direction: column; }\n.own-cal .quote-top b { font-size: 14px; }\n.own-cal .quote-top .muted { font-size: 12px; }\n.own-cal .avatar { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 9999px; font-size: 13px; font-weight: 500; color: var(--ink); flex: none; }\n.own-cal .av-1 { background: color-mix(in srgb, var(--badge-orange) 34%, #fff); }\n.own-cal .av-2 { background: color-mix(in srgb, var(--badge-violet) 28%, #fff); }\n.own-cal .av-3 { background: color-mix(in srgb, var(--badge-emerald) 32%, #fff); }\n.own-cal .stars { margin-left: auto; color: var(--badge-orange); font-size: 13px; letter-spacing: 1px; }\n.own-cal .quote-card p { color: var(--body); margin: 0; }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-cal .pricing { padding: var(--section) 0; }\n.own-cal .pricing-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 44px; }\n.own-cal .tier { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 12px; padding: 32px; display: flex; flex-direction: column; }\n.own-cal .tier-featured { background: var(--surface-dark); border-color: var(--surface-dark); color: var(--on-dark); }\n.own-cal .tier-name { font-family: var(--body-font); font-weight: 600; font-size: 22px; letter-spacing: -.02em; margin: 0 0 14px; }\n.own-cal .tier-price { font-family: var(--display); font-weight: 600; font-size: 28px; letter-spacing: -.02em; margin: 0 0 8px; }\n.own-cal .tier .check-list li { color: var(--body); }\n.own-cal .tier-featured .check-list li { color: var(--on-dark-soft); }\n.own-cal .tier-featured .check-list li::before { background: var(--surface-dark-elevated); border-color: var(--on-dark-soft); }\n.own-cal .tier-featured .check-list li::after { border-color: var(--on-dark); }\n.own-cal .tier .btn { margin-top: 22px; }\n.own-cal .tier-featured .btn-secondary { background: transparent; color: var(--on-dark); border-color: var(--on-dark-soft); }\n\n/* ── CTA band ────────────────────────────────────────────────────────── */\n.own-cal .cta-band { padding: clamp(40px, 6cqi, 72px) 0; }\n.own-cal .cta-inner { background: var(--surface-card); border-radius: 12px; padding: clamp(36px, 5cqi, 48px); text-align: center; display: grid; justify-items: center; gap: 12px; }\n.own-cal .cta-inner .btn { margin-top: 8px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-cal .foot { background: var(--surface-dark); color: var(--on-dark-soft); padding: clamp(48px, 6cqi, 64px) 0 28px; }\n.own-cal .foot-grid { display: grid; grid-template-columns: 1.4fr repeat(4, 1fr); gap: 24px; padding-bottom: 40px; }\n.own-cal .foot-word { font-family: var(--display); font-weight: 600; font-size: 20px; letter-spacing: -.03em; color: var(--on-dark); margin: 0 0 10px; }\n.own-cal .foot-tag { font-size: 14px; color: var(--on-dark-soft); margin: 0; }\n.own-cal .foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-cal .foot-h { font-size: 13px; font-weight: 600; color: var(--on-dark); margin: 0 0 4px; }\n.own-cal .foot-col a { font-size: 14px; color: var(--on-dark-soft); }\n.own-cal .foot-col a:hover { color: var(--on-dark); }\n.own-cal .foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid rgba(255,255,255,.1); font-size: 13px; }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-cal .hero-grid, .own-cal .product-grid { grid-template-columns: 1fr; }\n  .own-cal .feature-grid, .own-cal .quote-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-cal .pricing-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-cal .foot-grid { grid-template-columns: 1.4fr repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-cal .nav-links { display: none; }\n  .own-cal .nav-signin { display: none; }\n  .own-cal .feature-grid, .own-cal .quote-grid, .own-cal .pricing-grid, .own-cal .mock-body { grid-template-columns: 1fr; }\n  .own-cal .foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-cal .foot-grid { grid-template-columns: 1fr; }\n  .own-cal .hero-tabs { width: 100%; justify-content: space-between; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-cal *, .own-cal *::before, .own-cal *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — own-layout behaviour for showcase.html ══════════════════
   The hero nav-pill-group switches the visible product view label; the
   mock's "confirm" is inert. Query only inside root, clean up on unmount. */
(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  window.OWN_LAYOUTS['cal'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var timer = 0;

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(sel) { return root.querySelector(sel); }
      function $$(sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); }

      var views = ['Personal', 'Teams', 'Enterprise'];
      on($('.hero-tabs'), 'click', function (e) {
        var b = e.target.closest('[role="tab"]');
        if (!b) return;
        $$('.hero-tabs .tab').forEach(function (t) { t.setAttribute('aria-selected', String(t === b)); });
        var title = $('.mock-title');
        var label = views[$$('.hero-tabs .tab').indexOf(b)] || 'Teams';
        if (title) title.textContent = 'Northwind · ' + label + ' ops';
      });

      on($('.mock-confirm'), 'click', function () {
        var b = $('.mock-confirm');
        if (!b) return;
        var was = b.textContent;
        b.textContent = 'Confirmed';
        window.clearTimeout(timer);
        timer = window.setTimeout(function () { if (b) b.textContent = was; }, 1200);
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        if (timer) window.clearTimeout(timer);
      };
    }
  };
})();
